CREATE TABLE IF NOT EXISTS fn_wallets(namespace TEXT NOT NULL,id TEXT NOT NULL,customer TEXT NOT NULL,asset TEXT NOT NULL,network TEXT NOT NULL,scale INTEGER NOT NULL,kind TEXT NOT NULL,PRIMARY KEY(namespace,id),FOREIGN KEY(namespace,id) REFERENCES ca_accounts(namespace,id));
CREATE TABLE IF NOT EXISTS fn_orders(namespace TEXT NOT NULL REFERENCES demo_batches(namespace),id TEXT NOT NULL,kind TEXT NOT NULL,customer TEXT NOT NULL,asset TEXT NOT NULL,network TEXT NOT NULL,amount_minor TEXT NOT NULL,fee_minor TEXT NOT NULL,approval TEXT NOT NULL,execution TEXT NOT NULL,state TEXT NOT NULL,risk TEXT NOT NULL,revision INTEGER NOT NULL,requester TEXT NOT NULL,parent_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(namespace,id),FOREIGN KEY(namespace,parent_id) REFERENCES fn_orders(namespace,id));
CREATE INDEX IF NOT EXISTS fn_order_customer ON fn_orders(namespace,customer,created_at,id);
CREATE INDEX IF NOT EXISTS fn_order_status ON fn_orders(namespace,kind,approval,execution,created_at);
CREATE INDEX IF NOT EXISTS fn_order_parent ON fn_orders(namespace,parent_id);
CREATE TABLE IF NOT EXISTS fn_quotes(namespace TEXT NOT NULL REFERENCES demo_batches(namespace),id TEXT NOT NULL,actor TEXT NOT NULL,customer TEXT NOT NULL,expires_at TEXT NOT NULL,used_by TEXT,data_json TEXT NOT NULL,PRIMARY KEY(namespace,id));
CREATE TABLE IF NOT EXISTS fn_holds(namespace TEXT NOT NULL,order_id TEXT NOT NULL,account_id TEXT NOT NULL,amount_minor TEXT NOT NULL,PRIMARY KEY(namespace,order_id,account_id),FOREIGN KEY(namespace,order_id) REFERENCES fn_orders(namespace,id),FOREIGN KEY(namespace,account_id) REFERENCES fn_wallets(namespace,id));
CREATE INDEX IF NOT EXISTS fn_hold_account ON fn_holds(namespace,account_id);
CREATE TABLE IF NOT EXISTS fn_reviews(namespace TEXT NOT NULL,order_id TEXT NOT NULL,revision INTEGER NOT NULL,actor TEXT NOT NULL,node TEXT NOT NULL,decision TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(namespace,order_id,revision,actor),FOREIGN KEY(namespace,order_id) REFERENCES fn_orders(namespace,id));
CREATE TABLE IF NOT EXISTS fn_jobs(namespace TEXT NOT NULL,order_id TEXT NOT NULL,revision INTEGER NOT NULL,submission_key TEXT NOT NULL,mode TEXT NOT NULL,queries INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(namespace,order_id),UNIQUE(namespace,submission_key),FOREIGN KEY(namespace,order_id) REFERENCES fn_orders(namespace,id));
CREATE TABLE IF NOT EXISTS fn_events(namespace TEXT NOT NULL,event_id TEXT NOT NULL,order_id TEXT NOT NULL,digest TEXT NOT NULL,payload_json TEXT NOT NULL,result TEXT NOT NULL,received_at TEXT NOT NULL,PRIMARY KEY(namespace,event_id),FOREIGN KEY(namespace,order_id) REFERENCES fn_orders(namespace,id));
CREATE TABLE IF NOT EXISTS fn_movements(namespace TEXT NOT NULL,id TEXT NOT NULL,order_id TEXT NOT NULL,journal_id TEXT NOT NULL,account_id TEXT NOT NULL,customer TEXT NOT NULL,kind TEXT NOT NULL,asset TEXT NOT NULL,network TEXT NOT NULL,amount_minor TEXT NOT NULL,before_minor TEXT NOT NULL,after_minor TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(namespace,id),UNIQUE(namespace,journal_id,account_id),FOREIGN KEY(namespace,order_id) REFERENCES fn_orders(namespace,id),FOREIGN KEY(namespace,journal_id) REFERENCES ca_journals(namespace,id),FOREIGN KEY(namespace,account_id) REFERENCES fn_wallets(namespace,id));
CREATE INDEX IF NOT EXISTS fn_movement_query ON fn_movements(namespace,customer,asset,network,created_at,id);
CREATE INDEX IF NOT EXISTS fn_movement_order ON fn_movements(namespace,order_id);
CREATE TABLE IF NOT EXISTS fn_requests(namespace TEXT NOT NULL REFERENCES demo_batches(namespace),actor TEXT NOT NULL,request_id TEXT NOT NULL,digest TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(namespace,actor,request_id));
CREATE TABLE IF NOT EXISTS fn_audit(namespace TEXT NOT NULL REFERENCES demo_batches(namespace),id TEXT NOT NULL,order_id TEXT,actor TEXT NOT NULL,action TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(namespace,id));
CREATE INDEX IF NOT EXISTS fn_audit_order ON fn_audit(namespace,order_id,created_at);
CREATE TRIGGER IF NOT EXISTS fn_movement_no_update BEFORE UPDATE ON fn_movements BEGIN SELECT RAISE(ABORT,'Posted movements are immutable'); END;
CREATE TRIGGER IF NOT EXISTS fn_movement_no_delete BEFORE DELETE ON fn_movements BEGIN SELECT RAISE(ABORT,'Posted movements are immutable'); END;
